○整数型: fact(整数型: n)
  if (n が 0 と等しい)
    return 1
  else
    return n × fact(n - 1)
  endif

○整数型: gcd(整数型: a, 整数型: b)
  if (b が 0 と等しい)
    return a
  else
    return gcd(b, a を b で割った余り)
  endif

